S.append(CR(c,B+' · 5','Thực hành 2: sửa định dạng',"h1,h2 {font-family: sans-serif;\n        font-size: 16px;\n        color: blue;\n        text-align: center;}\np {text-align: justify;\n   text-indent: 2em;}\nstrong,em {font-size: 100%;}",'<div style="font-size:21px;line-height:1.35"><h2 style="font-family:sans-serif;color:blue;text-align:center;font-size:22px;margin:0">Lịch sử CSS</h2><p style="text-align:justify;text-indent:2em;margin:4px 0">Ý tưởng chính của CSS là tạo ra các mẫu định dạng <strong>riêng, độc lập</strong> cho phần tử <em>HTML</em> của trang web.</p></div>',WARN('SGK ghi <code>font-size: 199%</code> là in lỗi; dùng <b>100%</b> để chữ đậm, nghiêng giữ nguyên cỡ.'),19))
S.append(S2(c,'TRỌNG TÂM','Những điều phải nhớ',card('Ghi nhớ',ul(['<b>font-family</b> (5 loại), <b>font-size</b>, <b>font-style: italic</b>, <b>font-weight</b>.','<b>color</b>: màu chữ; <b>*</b> chọn mọi phần tử.','<b>line-height, text-align, text-decoration, text-indent</b>.','<b>Kế thừa</b>: con, cháu nhận mẫu của cha; riêng <b>text-decoration không kế thừa</b>.','Ưu tiên: <b>!important</b> cao nhất; cùng bộ chọn → mẫu <b>sau</b>; <b>*</b> thấp nhất.'],6)),T(tr('Muốn…','Dùng',h=True)+tr('Chữ nghiêng','font-style: italic',m=True)+tr('Căn đều hai bên','text-align: justify',m=True)+tr('Thụt dòng đầu','text-indent: 2em',m=True)+tr('Gạch ngang chữ','text-decoration: line-through',m=True))+WARN('Viết đúng: <code>italic</code> (không phải italics), <code>text-align</code> (không phải line-align).')))
